import * as E from './engine.js';
import * as Q from './report.js';
const node=(tag,text,cls)=>{const e=document.createElement(tag);if(text!=null)e.textContent=text;if(cls)e.className=cls;return e;};
const money=v=>Number.isFinite(v)?Math.round(v).toLocaleString('ko-KR'):'-';
const percent=v=>Number.isFinite(v)?(v>0?'+':'')+v.toFixed(1)+'%':'-';
function table(title,rows,columns){const section=node('section',null,'report-section');section.append(node('h3',title));const frame=node('div',null,'report-table-frame'),t=node('table',null,'report-table'),head=node('thead'),hr=node('tr'),body=node('tbody');for(const [label]of columns)hr.append(node('th',label));head.append(hr);for(const r of rows){const tr=node('tr');for(const [,value,numeric]of columns)tr.append(node('td',value(r),numeric?'numeric':''));body.append(tr);}if(!rows.length){const tr=node('tr'),td=node('td','해당 거래 없음');td.colSpan=columns.length;tr.append(td);body.append(tr);}t.append(head,body);frame.append(t);section.append(frame);return section;}
function chart(title,rows,key,count=false){
 const box=node('div',null,'report-chart');box.append(node('h4',title));const NS='http://www.w3.org/2000/svg',svg=document.createElementNS(NS,'svg');svg.setAttribute('viewBox','0 0 700 230');svg.setAttribute('role','img');svg.setAttribute('aria-label',title);const add=(tag,attrs,text)=>{const n=document.createElementNS(NS,tag);for(const[k,v]of Object.entries(attrs))n.setAttribute(k,v);if(text!=null)n.textContent=text;svg.append(n);return n;};
 const values=rows.map(r=>r[key]).filter(v=>Number.isFinite(v)&&(count||v>0));if(!values.length){box.append(node('p','관측값 없음'));return box;}
 const lo=count?0:Math.min(...values)*.92,hi=count?Math.max(3,Math.ceil(Math.max(...values)/3)*3):Math.max(...values)*1.08||1,x=i=>65+i*600/Math.max(1,rows.length-1),y=v=>185-(v-lo)/Math.max(1,hi-lo)*155;
 for(let i=0;i<4;i++){const v=lo+(hi-lo)*i/3;add('line',{x1:65,x2:665,y1:y(v),y2:y(v),stroke:'#e1e7ee'});add('text',{x:56,y:y(v)+4,'text-anchor':'end',class:'chart-label'},money(v));}
 let previous=null;
 rows.forEach((r,i)=>{const v=r[key];if(Number.isFinite(v)&&(count||r.count>0)){if(count)add('rect',{x:x(i)-Math.min(10,220/rows.length),y:y(v),width:Math.min(20,440/rows.length),height:185-y(v),fill:'#75aef1'});else{if(previous)add('line',{x1:x(previous.i),y1:y(previous.v),x2:x(i),y2:y(v),stroke:'#0071e3','stroke-width':2,'stroke-dasharray':i-previous.i>1?'5 5':''});const dot=add('circle',{cx:x(i),cy:y(v),r:4,fill:'#0071e3',tabindex:0});const tip=document.createElementNS(NS,'title');tip.textContent=r.period+' · '+money(v)+(key==='average'?'만원/평':'만 원')+' · '+r.count+'건';dot.append(tip);previous={i,v};}}if(i===0||i===rows.length-1||i%Math.max(1,Math.ceil(rows.length/6))===0)add('text',{x:x(i),y:210,'text-anchor':'middle',class:'chart-label'},r.period);});
 box.append(svg);return box;
}
export function renderReport(report,source){
 const root=node('article',null,'report-document');root.append(node('h2','주요 아파트 시장가격 종합 리포트'));
 const conclusion=node('section',null,'report-conclusion');conclusion.append(node('h3','시장가격 결론'));for(const line of Q.conclusions(report)){const p=node('p',line);p.contentEditable='true';p.setAttribute('aria-label','수정 가능한 리포트 결론');conclusion.append(p);}root.append(conclusion);
 const {mode,from,to,referenceYear,maxAge,frequency}=report.options;const criteria=node('section',null,'report-section');criteria.append(node('h3','조사 대상·분석 기준'));criteria.append(node('p',`조사 기간 ${from||'-'} ~ ${to||'-'} · 건축년도 ${referenceYear-maxAge}~${referenceYear}년 · 전용면적 버림 기준 59·84타입 중 선택 · ${frequency==='quarter'?'분기별':'월별'} · 현재 지역·계약·사례 포함 설정 반영`, 'hint'));root.append(criteria);
 const identity=[['행정동',r=>r.dong],['시군구',r=>r.region],['단지명',r=>r.name],['건축년도',r=>r.year],['세대수',r=>r.households?money(r.households):'미확인',true],['타입',r=>r.type+'타입']];
 const amounts=[['최소 거래가격',r=>money(r.priceMinimum),true],['최대 거래가격',r=>money(r.priceMaximum),true],['평균 거래가격',r=>money(r.priceAverage),true],['평균 평당가',r=>money(r.average),true]];
 const count=['거래건수',r=>money(r.count),true];
 if(mode==='sale'){
  root.append(table('행정동별 가격 비교',report.districts,[...identity.slice(0,2),identity[5],['단지수',r=>money(r.complexCount),true],...amounts.slice(2),count]));
  root.append(table('단지별 59·84타입 가격 비교',report.apartments,[...identity,...amounts,['최소 평당가',r=>money(r.minimum),true],['최대 평당가',r=>money(r.maximum),true],count]));
 }else{
  const jeonse=[['최소 전세금',r=>money(r.priceMinimum),true],['최대 전세금',r=>money(r.priceMaximum),true],['평균 전세금',r=>money(r.priceAverage),true],['최소 전세 평당가',r=>money(r.minimum),true],['최대 전세 평당가',r=>money(r.maximum),true],['평균 전세 평당가',r=>money(r.average),true],['거래건수',r=>money(r.jeonseCount),true]];
  root.append(table('행정동별 실제 전세가격',report.districts.filter(r=>r.jeonseCount),[...identity.slice(0,2),identity[5],...jeonse]));
  root.append(table('단지별 실제 전세가격',report.apartments.filter(r=>r.jeonseCount),[...identity,...jeonse]));
  root.append(table('단지별 실제 월세 계약조건',report.apartments.filter(r=>r.monthlyCount),[...identity,['평균 실제 보증금',r=>money(r.depositAverage),true],['최소 실제 월세',r=>money(r.rentMinimum),true],['최대 실제 월세',r=>money(r.rentMaximum),true],['평균 실제 월세',r=>money(r.rentAverage),true],['거래건수',r=>money(r.monthlyCount),true]]));
  root.append(node('p','월세 평균 보증금과 평균 월세는 동일 사례 집합의 항목별 평균이며, 실제 하나의 계약조건이나 동일 보증금 기준 가격을 뜻하지 않습니다.','hint'));
  root.append(table('실제 월세 개별 사례',report.rows.filter(r=>r.lease==='월세'),[['계약일',r=>r.date||'-'],...identity.slice(2),['실제 보증금',r=>money(r.deposit),true],['실제 월세',r=>money(r.rent),true],['신규·갱신',r=>r.contract||'미기재']]));
 }
 const groups=new Map();for(const r of report.periods){const k=JSON.stringify([r.name,r.address,r.type]);if(!groups.has(k))groups.set(k,[]);groups.get(k).push(r);}
 const caseSection=node('section',null,'report-section');caseSection.append(node('h3','단지별 사례·기간 추이'));root.append(caseSection);
 for(const rows of groups.values()){
  const r=rows[0],title=r.name+' · '+r.type+'타입 · '+r.address,section=node('details',null,'report-case');section.append(node('summary',title));
  const period=['기간',r=>r.period+(r.partial?' (부분)':'')];
  if(mode==='sale')section.append(table('기간별 거래가격',rows.filter(r=>r.count),[period,['평균 거래가격',r=>money(r.priceAverage),true],['전기 대비',r=>percent(r.priceChange),true],['평균 평당가',r=>money(r.average),true],['전기 대비',r=>percent(r.unitChange),true],count]));
  else section.append(table('기간별 실제 임대가격',rows.filter(r=>r.count),[period,['평균 전세금',r=>money(r.priceAverage),true],['전세금 전기 대비',r=>percent(r.priceChange),true],['평균 전세 평당가',r=>money(r.average),true],['평당가 전기 대비',r=>percent(r.unitChange),true],['평균 실제 보증금',r=>money(r.depositAverage),true],['평균 실제 월세',r=>money(r.rentAverage),true],['전세건수',r=>money(r.jeonseCount),true],['월세건수',r=>money(r.monthlyCount),true],count]));
  const charts=node('div',null,'report-chart-grid');charts.append(chart(mode==='sale'?'평균 거래가격 (만 원)':'평균 전세금 (만 원)',rows,'priceAverage'),chart(mode==='sale'?'평균 평당가 (만원/평)':'평균 전세 평당가 (만원/평)',rows,'average'),chart('거래건수 (건)',rows,'count',true));if(mode==='rent')charts.append(chart('평균 실제 월세 (만 원/월)',rows,'rentAverage'));section.append(charts);caseSection.append(section);
 }
 if(mode==='rent')root.append(table('기준 보증금으로 환산한 월세 — 참고 지표',report.apartments.filter(r=>r.monthlyCount),[...identity,['최소 환산 월세',r=>money(r.adjustedMinimum),true],['최대 환산 월세',r=>money(r.adjustedMaximum),true],['평균 환산 월세',r=>money(r.adjustedAverage),true],['환산 가능 건수',r=>money(r.adjustedCount),true],['거래건수',r=>money(r.monthlyCount),true]]));
 const basis=node('section',null,'report-section');basis.append(node('h3','출처·분석 기준'),node('pre',source),node('p','금액: 만 원 · 월세: 만 원/월 · 평당가: 만원/평. 거래별 산술평균이며 가격 범위는 조사 기간의 관측 범위입니다. 행정동은 원본 법정동 기준입니다. 건축년도만으로 연령을 계산합니다. 세대수는 단지 전체 세대수이며 타입별 세대수가 아닙니다. 전기 대비는 직전 달·분기 기준이며, 전기 거래가 없거나 비교 기간이 부분 기간이면 -로 표시합니다. 점선은 빈 기간을 연결한 참고선입니다.','hint'));if(report.unknownYears)basis.append(node('p','건축년도 미확인 '+report.unknownYears+'건은 대상 선정에서 제외했습니다.','hint'));root.append(basis);
 const toc=node('nav',null,'report-toc');toc.setAttribute('aria-label','리포트 목차');toc.append(node('h3','목차'));const list=node('ol');const sections=[...root.children].filter(n=>n.tagName==='SECTION');for(const [i,section]of sections.entries()){section.id='report-section-'+(i+1);const heading=section.querySelector('h3'),label=heading?.textContent||'분석';if(heading)heading.textContent=(i+1)+'. '+label;const item=node('li'),a=node('a',label);a.href='#'+section.id;item.append(a);list.append(item);}toc.append(list);conclusion.after(toc);return root;
}
export function bindReport(getContext,copy){
 const $=s=>document.querySelector(s);let referenceSource=null,targets=new Map(),selection=new Set();
 const context=()=>getContext();
 const options=()=>{const c=context(),range=E.sourceDateRange(c.source,c.raw);return {mode:c.mode,referenceYear:Number($('#reportYear').value),maxAge:Number($('#reportAge').value),types:[...document.querySelectorAll('[name=reportType]:checked')].map(n=>Number(n.value)),frequency:$('#reportFrequency').value,from:c.filters.from||range.from,to:c.filters.to||range.to,selected:selection};};
 function refreshTargets(reset=false){const c=context(),range=E.sourceDateRange(c.source,c.raw);if(referenceSource!==c.source){$('#reportYear').value=Number((range.to||new Date().toISOString()).slice(0,4));referenceSource=c.source;reset=true;}const opts=options();targets=new Map(Q.targetRows(c.rows,{...opts,selected:null}).map(r=>[E.propertyKey(r),r]));selection=reset?new Set(targets.keys()):new Set([...selection].filter(k=>targets.has(k)));const list=$('#reportTargets');list.replaceChildren();for(const [key,r]of [...targets].sort((a,b)=>a[1].name.localeCompare(b[1].name,'ko')||a[1].address.localeCompare(b[1].address,'ko'))){const label=node('label',null,'check-label'),box=node('input');box.type='checkbox';box.checked=selection.has(key);box.addEventListener('change',()=>{box.checked?selection.add(key):selection.delete(key);syncAll();});label.append(box,node('span',r.name+' · '+r.dong+' · '+r.address));list.append(label);}syncAll();}
 function syncAll(){const all=$('#reportSelectAll');all.checked=targets.size>0&&selection.size===targets.size;all.indeterminate=selection.size>0&&selection.size<targets.size;$('#reportTargetCount').textContent=selection.size+'/'+targets.size+'개 단지 선택';}
 function generate(){const c=context(),opts=options();if(!Number.isInteger(opts.referenceYear)||opts.referenceYear<1900||opts.referenceYear>2200||!Number.isInteger(opts.maxAge)||opts.maxAge<0||opts.maxAge>100){$('#reportStatus').textContent='기준연도와 건축년도 범위를 확인해 주세요.';return;}const report=Q.buildReport(c.rows,opts);$('#reportContent').replaceChildren(renderReport(report,c.sourceText));$('#reportStatus').textContent=report.complexCount+'개 단지 · '+report.rows.length+'건 · 결론은 클릭해서 수정할 수 있습니다. 조건을 변경하면 리포트 작성을 다시 누르세요.';$('#copyReport').disabled=$('#printReport').disabled=false;}
 for(const s of ['#reportYear','#reportAge','[name=reportType]'])for(const input of document.querySelectorAll(s))input.addEventListener('change',()=>refreshTargets(true));
 $('#reportSelectAll').addEventListener('change',e=>{selection=e.target.checked?new Set(targets.keys()):new Set();for(const box of $('#reportTargets').querySelectorAll('input'))box.checked=e.target.checked;syncAll();});
 $('#generateReport').addEventListener('click',()=>{refreshTargets();generate();});
 $('#copyReport').addEventListener('click',()=>{const content=$('#reportContent'),clone=content.cloneNode(true);for(const details of clone.querySelectorAll('details')){const section=node('section');for(const child of [...details.children])section.append(child.tagName==='SUMMARY'?node('h3',child.textContent):child);details.replaceWith(section);}for(const n of clone.querySelectorAll('[contenteditable]'))n.removeAttribute('contenteditable');for(const t of clone.querySelectorAll('table'))t.style.cssText='border-collapse:collapse;font-family:Malgun Gothic,Arial;font-size:10pt';for(const c of clone.querySelectorAll('th,td'))c.style.cssText='border:1px solid #ccd3dd;padding:6px;text-align:'+(c.classList.contains('numeric')?'right':'left');copy({text:[...clone.querySelectorAll('h2,h3,h4,p,pre,table')].filter(n=>n.tagName!=='P'||!n.closest('table')).map(n=>n.tagName==='TABLE'?[...n.rows].map(r=>[...r.cells].map(c=>c.textContent).join('\t')).join('\n'):n.textContent).join('\n\n'),html:'<html><head><meta charset="utf-8"></head><body>'+clone.innerHTML+'</body></html>'});});
 $('#printReport').addEventListener('click',()=>{const closed=[...$('#reportContent').querySelectorAll('details:not([open])')];closed.forEach(d=>d.open=true);window.addEventListener('afterprint',()=>closed.forEach(d=>d.open=false),{once:true});window.print();});
 return {open:()=>{const c=context();if(!c.source||c.kind!=='아파트')return;refreshTargets(true);generate();},invalidate:()=>{if(!$('#reportPanel').hidden)$('#reportStatus').textContent='분석 조건이 변경됐습니다. 리포트 작성을 다시 누르면 최신 결과를 반영합니다.';}};
}
